#!/usr/bin/env bash
set -euo pipefail

if [[ $# -ne 1 ]]; then
  printf 'usage: bash setup-exercise.sh NEW_DIRECTORY\n' >&2
  exit 2
fi
TARGET=$1
if [[ -e "$TARGET" ]]; then
  printf 'refusing existing path: %s\n' "$TARGET" >&2
  exit 3
fi
command -v node >/dev/null
printf 'Node version: '
node --version
mkdir -p "$TARGET/src" "$TARGET/fixtures" "$TARGET/tests" "$TARGET/reference"

cat > "$TARGET/src/eligibility.mjs" <<'EOF'
export function eligible(record) {
  return record.age > 18 && record.active === true;
}
EOF

cat > "$TARGET/fixtures/cases.mjs" <<'EOF'
export const cases = [
  { label: 'positive adult active', record: { age: 21, active: true }, expected: true },
  { label: 'negative minor active', record: { age: 17, active: true }, expected: false },
  { label: 'negative adult inactive', record: { age: 21, active: false }, expected: false },
  { label: 'changed boundary adult active', record: { age: 18, active: true }, expected: true }
];
EOF

cat > "$TARGET/reference/eligibility.mjs" <<'EOF'
export function eligible(record) {
  return record.age >= 18 && record.active === true;
}
EOF

cat > "$TARGET/tests/immutable-test.mjs" <<'EOF'
import { eligible } from '../src/eligibility.mjs';
import { cases } from '../fixtures/cases.mjs';

let passed = 0;
let failed = 0;
for (const testCase of cases) {
  const actual = eligible(testCase.record);
  if (actual === testCase.expected) {
    console.log(`PASS ${testCase.label}`);
    passed += 1;
  } else {
    console.log(`FAIL ${testCase.label}: expected ${testCase.expected}, got ${actual}`);
    failed += 1;
  }
}
console.log(`Summary: ${passed} passed, ${failed} failed`);
process.exitCode = failed === 0 ? 0 : 1;
EOF

cat > "$TARGET/README.md" <<'EOF'
# Copilot boundary exercise

Run `node tests/immutable-test.mjs`. Repair only the single comparison predicate in `src/eligibility.mjs`. Do not edit tests, fixtures, or reference.
EOF

chmod a-w "$TARGET/tests/immutable-test.mjs"
chmod a-w "$TARGET/fixtures/cases.mjs"
chmod a-w "$TARGET/reference/eligibility.mjs"

git -C "$TARGET" init -q
git -C "$TARGET" config user.name 'Project 42 Learner'
git -C "$TARGET" config user.email 'learner@example.invalid'
git -C "$TARGET" add .
git -C "$TARGET" commit -qm 'baseline exact exercise fixtures'
git -C "$TARGET" branch -M main
git -C "$TARGET" branch baseline
printf 'Created fresh exercise at %s\n' "$TARGET"
printf 'Baseline is tracked. No remote or push was configured.\n'
printf 'Run: cd %s && node tests/immutable-test.mjs\n' "$TARGET"
